const out = '/workspace/docs/qa/bouquet-detail/preferences-001/final-local';
(async () => {
 const { chromium } = await import('@playwright/test');
 const fs = await import('node:fs');
 const browser = await chromium.launch({headless:true}); const results=[];
 for (const [locale,width] of (process.env.SMOKE ? [['en',360]] : [['en',360],...['en','ru','sr'].flatMap(l=>[320,360,768,1440].filter(w=>!(l==='en'&&w===360)).map(w=>[l,w]))])) {
  const page=await browser.newPage({viewport:{width,height:1000}}); const errors=[]; page.on('pageerror',e=>errors.push(e.message));
  const checks=[]; const check=(name,ok,detail='')=>checks.push({name,ok:!!ok,detail});
  try {
   const response=await page.goto(`http://127.0.0.1:3219/${locale}/fixture/detail`,{waitUntil:'networkidle'}); await page.evaluate(()=>document.fonts.ready);
   check('http',response.status()===200,response.status());
   const section=page.locator('section').filter({has:page.locator('#preferred-date')});
   const radios=section.locator('input[type=radio]'), boxes=section.locator('input[type=checkbox]'), date=page.locator('#preferred-date'), msg=page.locator('#card-message');
   if(locale==='en') await section.screenshot({path:`${out}/initial-${width}.png`});
   const metrics=await section.evaluate(async root=>{
    const r=e=>{const b=e.getBoundingClientRect();return {x:b.x,y:b.y,width:b.width,height:b.height}};
    const labels=[...root.querySelectorAll('label')].filter(e=>e.querySelector('input')); const issues=[];
    for(const el of [root.querySelector('p'),...labels.map(x=>x.querySelector('[class*="LabelText"]'))]) { const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode())for(const m of n.data.matchAll(/\S+/gu)){const range=document.createRange();range.setStart(n,m.index);range.setEnd(n,m.index+m[0].length);const rects=[...range.getClientRects()]; const bound=(el.closest('label')||el).getBoundingClientRect();if(rects.length!==1||rects.some(q=>q.left<bound.left-0.5||q.right>bound.right+0.5||q.top<bound.top-0.5||q.bottom>bound.bottom+0.5))issues.push({word:m[0],rects:rects.length});} }
    const collisions=labels.map(e=>{const a=e.querySelector('img').getBoundingClientRect(),b=e.querySelector('[class*=LabelText]').getBoundingClientRect();return a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;});
    const imgs=await Promise.all([...root.querySelectorAll('img')].map(async e=>{try{await e.decode();return {alt:e.alt,src:e.currentSrc,naturalWidth:e.naturalWidth,...r(e)}}catch(x){return {error:String(x)}}}));
    return {section:r(root),fieldsets:[...root.querySelectorAll('fieldset')].map(r),cards:labels.map(e=>({label:e.innerText,box:r(e),caption:r(e.querySelector('[class*=LabelText]')),font:getComputedStyle(e.querySelector('[class*=LabelText]')).font,html:e.innerHTML})),issues,collisions,imgs,overflow:document.documentElement.scrollWidth>innerWidth};
   });
   check('whole words',!metrics.issues.length,metrics.issues);check('no image text overlap',metrics.collisions.every(c=>!c),metrics.collisions);check('no overflow',!metrics.overflow);check('real decoded decorative images',metrics.imgs.length===6&&metrics.imgs.every(i=>!i.error&&i.alt===''&&i.naturalWidth>0&&i.width>0&&i.height>0&&i.src.includes('/_next/image')),metrics.imgs);
   if(locale==='en'&&width===360) check('native mobile three 96px cards',metrics.cards.slice(0,3).every(c=>Math.abs(c.box.width-96)<0.1&&Math.abs(c.box.y-metrics.cards[0].box.y)<0.1),metrics.cards.slice(0,3).map(c=>c.box));
   if(locale==='en'&&[768,1440].includes(width)) {const widths=await section.evaluate(el=>{const p=el.parentElement,old=p.getAttribute('style'); const result=[];for(const w of [744,648]){p.style.maxWidth=`${w}px`;p.style.width=`${w}px`; result.push({section:el.getBoundingClientRect().width,cards:[...el.querySelectorAll('input[type=radio]')].map(e=>e.parentElement.getBoundingClientRect().width)});}p.setAttribute('style',old);return result;});check('native 704/608 container widths',widths.every((v,i)=>Math.abs(v.section-[704,608][i])<0.1&&v.cards.every(c=>Math.abs(c-[224,192][i])<0.1)),widths);}
   check('fullness visible marks and targets',await radios.evaluateAll(es=>es.every(e=>{const mark=e.parentElement.querySelector('[class*=radioMark]'), b=e.parentElement.getBoundingClientRect(), m=mark?.getBoundingClientRect();return m&&m.width===16&&m.height===16&&b.width>=44&&b.height>=44;})));
   check('extras and field 44px targets',await section.evaluate(el=>[...el.querySelectorAll('input[type=checkbox]')].map(e=>e.parentElement).concat([el.querySelector('#preferred-date'),el.querySelector('#card-message')]).every(e=>{const b=e.getBoundingClientRect();return b.width>=44&&b.height>=44;})));
   check('defaults',await radios.nth(0).isChecked()&&!(await radios.nth(1).isChecked())&&!(await radios.nth(2).isChecked())&&await boxes.count()===3&&!(await boxes.nth(0).isChecked())&&!(await boxes.nth(1).isChecked())&&!(await boxes.nth(2).isChecked()));
   await msg.fill('Preserved note');await boxes.nth(0).locator('..').click();await boxes.nth(2).locator('..').click();await boxes.nth(2).locator('..').click();check('message enabled while greeting off',await msg.isEnabled()&&await msg.inputValue()==='Preserved note');await boxes.nth(2).locator('..').click();await radios.nth(1).locator('..').click();
   for(const [value,valid] of [['',true],['   ',false],['29.02.2024',true],['29.02.2025',false],['31.04.2026',false],['bad-date',false],['01.01.2000',true],['01.01.0099',true]]) {await date.fill(value);await date.blur();const invalid=await date.getAttribute('aria-invalid');const desc=await date.getAttribute('aria-describedby');check('date '+value,invalid===String(!valid)&&(valid?desc===null:desc==='date-error'&&await page.locator('#date-error[role=alert]').isVisible()),{invalid,desc});}
   check('no date rules',await date.getAttribute('type')==='text'&&await date.getAttribute('min')===null&&await date.getAttribute('max')===null&&await date.getAttribute('required')===null);
   check('state preserved',await msg.inputValue()==='Preserved note'&&await radios.nth(1).isChecked()&&await boxes.nth(0).isChecked()&&!(await boxes.nth(1).isChecked())&&await boxes.nth(2).isChecked());
   await radios.nth(0).focus();await page.keyboard.press('ArrowRight');check('native radio keyboard',await radios.nth(1).isChecked());await boxes.nth(1).focus();await page.keyboard.press('Space');check('native checkbox keyboard',await boxes.nth(1).isChecked());
   const focus=[]; for(const input of [...await radios.all(),...await boxes.all(),date,msg]){await input.focus();await page.keyboard.press('Tab');await input.focus();focus.push(await input.evaluate(e=>{const target=e.type==='radio'||e.type==='checkbox'?e.nextElementSibling:e; const s=getComputedStyle(target), r=target.getBoundingClientRect(), pad=parseFloat(s.outlineWidth)+parseFloat(s.outlineOffset); let clipped=r.left-pad<0||r.right+pad>innerWidth;for(let a=target.parentElement;a&&a!==document.body;a=a.parentElement){const st=getComputedStyle(a),b=a.getBoundingClientRect();if(/hidden|clip/.test(st.overflowX)&&(r.left-pad<b.left||r.right+pad>b.right))clipped=true;if(/hidden|clip/.test(st.overflowY)&&(r.top-pad<b.top||r.bottom+pad>b.bottom))clipped=true;}return {outline:s.outlineStyle,width:s.outlineWidth,offset:s.outlineOffset,clipped,rect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom}}}));}
   check('focus outline visible and unclipped',focus.every(f=>f.outline==='solid'&&f.width==='3px'&&f.offset==='3px'&&!f.clipped),focus);
   if(width===360){const series=[];for(const w of [359,360,361]){await page.setViewportSize({width:w,height:1000});series.push(await section.evaluate(el=>{const f=el.querySelector('fieldset'), cards=[...f.querySelectorAll('input[type=radio]')].map(e=>e.parentElement);const ys=cards.map(c=>Math.round(c.getBoundingClientRect().top));const first=ys[0];return {height:f.getBoundingClientRect().height,signature:cards.map((c,i)=>[ys[i]-first,Math.round(c.querySelector('[class*=radioLabelText]').getBoundingClientRect().height/20)]).map(([y,n])=>[y===0?0:y>0?1:-1,n])};}));}const same=(a,b)=>JSON.stringify(a.signature)===JSON.stringify(b.signature);check('conditional adjacent continuity',series.every((v,i)=>i===0||!same(v,series[i-1])||Math.abs(v.height-series[i-1].height)<6),series);}
   check('no browser errors',!errors.length,errors); results.push({locale,width,checks,metrics,focus});
  } catch(e){checks.push({name:'execution',ok:false,detail:String(e.stack)});results.push({locale,width,checks});}
  console.log(locale,width,checks.filter(c=>!c.ok).map(c=>c.name).join(', ')||'PASS'); await page.close();
 }
 fs.writeFileSync(`${out}/results.json`,JSON.stringify(results,null,2)); await browser.close();process.exit(results.some(r=>r.checks.some(c=>!c.ok))?1:0);
})().catch(e=>{console.error(e);process.exit(2)});
